begin;
update cheongla_private.push_settings set enabled=false;
update cheongla_private.membership_sms_settings set enabled=false;
do $$declare st uuid;pa uuid;ad uuid;mg uuid;ex uuid;fee uuid;tv uuid;mv uuid;v timestamptz;dv timestamptz;sv timestamptz;fv timestamptz;data jsonb;d date:='2096-11-05';today date:=(now()at time zone 'Asia/Seoul')::date;r record;
begin
select id into st from public.cheongla_profiles where role='student'and approval_status='approved'and membership_state='active'limit 1;
select id into pa from public.cheongla_profiles where role='parent'and approval_status='approved'and membership_state='active'limit 1;
select id into ad from public.cheongla_profiles where role in('owner','english_director','math_director')and approval_status='approved'and membership_state='active'limit 1;
select id into mg from public.cheongla_profiles where role='manager'and approval_status='approved'and membership_state='active'limit 1;
if st is null or pa is null or ad is null or mg is null then raise exception 'FAIL missing fixture roles';end if;
insert into public.cheongla_parent_students(parent_id,student_id,created_by)values(pa,st,ad)on conflict do nothing;
perform set_config('request.jwt.claim.sub',ad::text,true);
insert into public.cheongla_exams(title,exam_on,deadline,status)values('역할·영구삭제 검증용','2096-11-20','2096-11-19 12:00+09','open')returning id into ex;
perform set_config('request.jwt.claim.sub',st::text,true);
perform public.cheongla_apply_student_exam(st,ex,'register');
if not cheongla_private.can_apply_for(st)then raise exception 'FAIL student applicant';end if;
perform set_config('request.jwt.claim.sub',pa::text,true);
if cheongla_private.can_apply_for(st)or cheongla_private.can_view_exams()then raise exception 'FAIL parent applicant permission';end if;
begin perform public.cheongla_apply_student_exam(st,ex,'register');raise exception 'FAIL parent applied';exception when insufficient_privilege then null;end;
begin perform public.cheongla_apply_exam(ex,'register');raise exception 'FAIL parent legacy applied';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',ad::text,true);
insert into public.cheongla_meal_forms(month,deadline,unit_price)values('2096-11-01','2096-10-29',7500)returning updated_at into fv;
perform set_config('request.jwt.claim.sub',st::text,true);
perform public.cheongla_submit_student_meal(st,'2096-11-01',array[d],array[d],'',null,fv);
select updated_at into sv from public.cheongla_meal_submissions where month='2096-11-01'and student_id=st;
begin perform public.cheongla_submit_student_meal(st,'2096-11-01','{}',array[d],'',sv,fv);raise exception 'FAIL student self cancellation';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
begin perform public.cheongla_submit_meal_form('2096-11-01','{}',array[d],'',sv,fv);raise exception 'FAIL legacy student cancellation';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
perform set_config('request.jwt.claim.sub',pa::text,true);
begin perform public.cheongla_read_meal_form('2096-11-01');raise exception 'FAIL parent meal read';exception when insufficient_privilege then null;end;
begin perform public.cheongla_submit_student_meal(st,'2096-11-01',array[d],array[d],'',sv,fv);raise exception 'FAIL parent meal submit';exception when insufficient_privilege then null;end;
begin perform public.cheongla_cancel_meal_by_staff('2096-11-01',st,d,'lunch','전화 접수',sv);raise exception 'FAIL parent staff cancellation';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',mg::text,true);
begin perform public.cheongla_cancel_meal_by_staff('2096-11-01',st,today,'lunch','문자 접수',sv);raise exception 'FAIL same-day cancellation';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
begin perform public.cheongla_cancel_meal_by_staff('2096-11-01',st,d,'lunch','문자 접수',sv-interval '1 day');raise exception 'FAIL stale cancellation';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
perform public.cheongla_cancel_meal_by_staff('2096-11-01',st,d,'lunch','학부모 문자 요청 확인',sv);
if not exists(select 1 from public.cheongla_meal_submissions where month='2096-11-01'and student_id=st and lunch='{}'and dinner=array[d])then raise exception 'FAIL staff cancellation result';end if;
data:=public.cheongla_read_meal_form('2096-11-01');if jsonb_array_length(data->'cancellations')<>1 then raise exception 'FAIL cancellation audit';end if;
perform set_config('request.jwt.claim.sub',ad::text,true);
insert into public.cheongla_exam_fee_notices(exam_id,student_id,student_name,exam_title,exam_on,amount,due_on,status)values(ex,st,'검증 학생','검증 시험','2096-11-20',25000,today,'published')returning id into fee;
insert into public.cheongla_tuition_notices(student_id,student_name,billing_month,period_start,period_end,monthly_fee,billable_days,month_days,amount,due_on,status,daily_fee)values(st,'검증 학생','2096-11-01','2096-11-01','2096-11-30',450000,30,30,450000,today,'published',15000)returning id into tv;
select updated_at into sv from public.cheongla_meal_submissions where month='2096-11-01'and student_id=st;
mv:=public.cheongla_save_meal_bill_v2('2096-11-01',st,today,0,'',sv,null);select updated_at into v from public.cheongla_meal_bills where id=mv;
perform public.cheongla_publish_meal_bill(mv,'publish',v);
for r in select fee_kind,id,updated_at from cheongla_private.collection_notices where id in(fee,tv,mv)loop
 perform cheongla_private.notify_collection(r.fee_kind,r.id,false,'학부모 청구 검증','role-parent-test:'||r.id);
 if exists(select 1 from public.cheongla_notifications n join public.cheongla_profiles p on p.id=n.recipient_id where n.event_key='role-parent-test:'||r.id and p.role<>'parent')then raise exception 'FAIL fee alert non-parent';end if;
 if not exists(select 1 from public.cheongla_notifications where event_key='role-parent-test:'||r.id and recipient_id=pa)then raise exception 'FAIL parent fee alert absent';end if;
 perform set_config('request.jwt.claim.sub',st::text,true);if cheongla_private.can_read_collection(r.fee_kind,r.id)then raise exception 'FAIL student bill visibility';end if;
 perform set_config('request.jwt.claim.sub',pa::text,true);if not cheongla_private.can_read_collection(r.fee_kind,r.id)then raise exception 'FAIL parent bill visibility';end if;
 perform set_config('request.jwt.claim.sub',ad::text,true);
end loop;
select updated_at into v from public.cheongla_exam_fee_notices where id=fee;
perform public.cheongla_set_fee_payment('exam',fee,true,v,null);
update public.cheongla_exams set deleted_at=clock_timestamp(),updated_at=clock_timestamp()where id=ex returning updated_at,deleted_at into v,dv;
perform set_config('request.jwt.claim.sub',mg::text,true);
begin perform public.cheongla_purge_deleted_exam(ex,v,dv);raise exception 'FAIL manager purge';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',ad::text,true);
begin perform public.cheongla_purge_deleted_exam(ex,v-interval '1 day',dv);raise exception 'FAIL stale purge';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
perform public.cheongla_purge_deleted_exam(ex,v,dv);
if exists(select 1 from public.cheongla_exams where id=ex)or exists(select 1 from public.cheongla_exam_applications where exam_id=ex)or exists(select 1 from public.cheongla_exam_fee_notices where id=fee)then raise exception 'FAIL physical exam purge';end if;
if not exists(select 1 from cheongla_private.fee_payments where notice_kind='exam'and notice_id=fee and paid_at is not null)or not exists(select 1 from cheongla_private.exam_fee_archives where id=fee)or not exists(select 1 from cheongla_private.exam_purge_events where exam_id=ex)then raise exception 'FAIL financial archive';end if;
perform set_config('request.jwt.claim.sub',pa::text,true);data:=public.cheongla_billing_list('2096-11-01');if not exists(select 1 from jsonb_array_elements(data->'items')x where x->>'id'=fee::text and x->'_payment'->>'paid_at'is not null)then raise exception 'FAIL parent retained receipt';end if;
perform set_config('request.jwt.claim.sub',st::text,true);data:=public.cheongla_billing_list('2096-11-01');if jsonb_array_length(data->'items')<>0 then raise exception 'FAIL student billing';end if;
end;$$;
rollback;
select 'PASS: student-only applications, parent-only 3-cost bills/alerts, staff-only prior-day meal cancellation and audit, principal-only paid exam permanent deletion with financial and parent receipt retention. Fixtures/settings rolled back; no real SMS/push sent.' as result;
